css:
/* Fase 19 · editorial search preview */
.search-page{max-width:1220px}.search-page .results-panel{max-width:1130px;margin-inline:auto}
.results-panel #search-count{font-family:Georgia,serif!important;font-size:clamp(2rem,4vw,3.05rem)!important;font-weight:400!important;letter-spacing:-.045em;line-height:1.12;margin:0 0 7px;scroll-margin-top:20px}
.results-panel #search-count:focus:not(:focus-visible){outline:0}
.results-panel #search-context{font-size:.91rem;margin-bottom:22px}
.results-panel #search-results,.results-panel #search-related-list{display:grid!important;grid-template-columns:minmax(0,1fr)!important;gap:15px!important}
.results-panel .search-result-card{min-width:0;position:relative!important;display:flex!important;flex-direction:column!important;padding:0!important;gap:0!important;background:#fffcf6!important;border:1px solid #dbd9ce!important;border-radius:3px!important;overflow:hidden;box-shadow:0 12px 28px rgba(14,49,42,.035);transition:border-color .18s,box-shadow .18s,transform .18s}
.results-panel .search-result-card[hidden]{display:none!important}
.results-panel .search-result-card:hover{border-color:#b6b9a5!important;box-shadow:0 15px 32px rgba(14,49,42,.075);transform:translateY(-1px)}
.search-result-card .result-topline{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:17px 26px 0}
.search-result-card .result-place{color:#795a34;text-transform:uppercase;letter-spacing:.17em;font-size:.71rem;font-weight:750}
.search-result-card .result-types{color:#64716a;font-size:.76rem;text-align:right;text-transform:capitalize}
.search-result-card .result-main{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(220px,.7fr);gap:28px;padding:13px 26px 19px}
.results-panel .search-result-card h3{font-family:Georgia,serif!important;font-size:clamp(1.9rem,3vw,2.6rem)!important;letter-spacing:-.035em;font-weight:400;line-height:1.12;margin:0 0 13px}
.search-result-card h3 a{color:#173e35;text-decoration:none}.search-result-card h3 a:hover{text-decoration:underline;text-underline-offset:5px}
.results-panel .search-result-card .result-editorial{color:#46594f;font-size:.94rem;line-height:1.7;margin:0;max-width:70ch;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.search-result-card .result-facts{border-left:1px solid #dedfd3;padding-left:24px;display:flex;flex-direction:column;gap:10px}
.search-result-card .result-facts-label{display:block;color:#64766a;text-transform:uppercase;letter-spacing:.13em;font-size:.66rem;font-weight:760}
.results-panel .search-result-card .tags{margin:0;gap:6px}
.results-panel .search-result-card .tag{background:#eff0e8;color:#2c5042;border-radius:2px;padding:5px 8px;font-size:.73rem;line-height:1.3}
.search-result-card .result-official{color:#566a5e;font-size:.79rem;line-height:1.5;margin:0}
.search-result-card .result-address{margin:auto 0 0;color:#66756c;font-size:.79rem}
.results-panel .search-result-card .result-actions{display:flex;gap:0;align-items:stretch;margin:0;border-top:1px solid #e7e5d9;min-height:53px}
.search-result-card .result-primary{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:12px 27px;min-height:53px;flex:1;color:#123c35;text-decoration:none;font-size:.9rem;font-weight:720}
.search-result-card .result-primary:hover,.search-result-card .result-secondary:hover{background:#f3f0e5}
.search-result-card .result-primary span{font-size:1.2rem;font-weight:400;color:#a47c42}
.search-result-card .result-secondary{display:flex;align-items:center;justify-content:center;min-width:125px;padding:12px 21px;border-left:1px solid #e7e5d9;text-decoration:none;color:#3f5148;font-size:.83rem}
.search-page .filter-chip{background:#fdfaf3;border-radius:30px;border-color:#d2d7c9}
.search-page #search-page-count{color:#67756b;font-size:.78rem}
@media(max-width:680px){
.results-panel #search-count{font-size:clamp(1.85rem,8vw,2.5rem)!important}
.search-result-card .result-topline{padding:17px 19px 0;align-items:flex-start}
.search-result-card .result-types{max-width:48%;font-size:.71rem;line-height:1.4}
.search-result-card .result-main{grid-template-columns:minmax(0,1fr);gap:16px;padding:14px 19px 18px}
.results-panel .search-result-card h3{font-size:clamp(1.85rem,8.5vw,2.25rem)!important}
.results-panel .search-result-card .result-editorial{font-size:.9rem;line-height:1.62;-webkit-line-clamp:4}
.search-result-card .result-facts{border-left:0;border-top:1px solid #e8e6d9;padding:14px 0 0;gap:8px}
.search-result-card .result-address{margin-top:5px}
.search-result-card .result-primary{padding:12px 19px}
.search-result-card .result-secondary{min-width:94px;padding:10px 13px}
}
@media(prefers-reduced-motion:reduce){.results-panel .search-result-card{transition:none}}

.search-page #search-count:focus{outline:0!important}
